package br.com.gymetrics.dao;

import br.com.gymetrics.model.*; import br.com.gymetrics.util.ConexaoSQLite; import java.sql.*; import java.time.*; import java.util.*;

public class RegistroAcessoDAO {
    public void salvar(RegistroAcesso x)throws SQLException{try(Connection c=ConexaoSQLite.conectar();PreparedStatement p=c.prepareStatement("INSERT INTO registros_acesso(aluno_id,data_hora,tipo,observacao) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){if(x.getAluno()==null)p.setNull(1,Types.INTEGER);else p.setInt(1,x.getAluno().getId());p.setString(2,x.getDataHora().toString());p.setString(3,x.getTipo().name());p.setString(4,x.getObservacao());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())x.setId(r.getInt(1));}}}
    public List<RegistroAcesso> listarPorPeriodo(LocalDate i,LocalDate f)throws SQLException{List<RegistroAcesso> l=new ArrayList<>();String sql="SELECT r.*,a.nome,a.cpf,a.status FROM registros_acesso r LEFT JOIN alunos a ON a.id=r.aluno_id WHERE date(r.data_hora) BETWEEN ? AND ? ORDER BY r.data_hora";try(Connection c=ConexaoSQLite.conectar();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,i.toString());p.setString(2,f.toString());try(ResultSet r=p.executeQuery()){while(r.next()){Aluno a=null;if(r.getObject("aluno_id")!=null){a=new Aluno();a.setId(r.getInt("aluno_id"));a.setNome(r.getString("nome"));a.setCpf(r.getString("cpf"));a.setStatus(Aluno.Status.valueOf(r.getString("status")));}l.add(new RegistroAcesso(r.getInt("id"),a,LocalDateTime.parse(r.getString("data_hora")),RegistroAcesso.Tipo.valueOf(r.getString("tipo")),r.getString("observacao")));}}}return l;}
}
